// frontend/src/components/ChartView.js
import React from "react";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function ChartView({ chart }) {
  if (!chart || (!chart.price || chart.price.labels.length === 0) ) {
    return <div className="text-muted small">No chart data available. Ask about an area (e.g. "Analyze Wakad") or upload a dataset.</div>;
  }

  const price = chart.price;
  const demand = chart.demand;

  const datasets = [
    {
      label: "Price",
      data: price.series,
      yAxisID: "y",
      fill: false,
      tension: 0.2,
    }
  ];

  if (demand && demand.labels.length > 0) {
    datasets.push({
      label: "Demand",
      data: demand.series,
      yAxisID: "y1",
      fill: false,
      tension: 0.2,
    });
  }

  const data = {
    labels: price.labels,
    datasets
  };

  const options = {
    responsive: true,
    interaction: { mode: "index", intersect: false },
    scales: {
      y: { type: "linear", display: true, position: "left" },
      y1: { type: "linear", display: !!(demand && demand.labels.length > 0), position: "right" }
    }
  };

  return <div style={{height: 300}}><Line data={data} options={options} /></div>;
}
